    show_position: bool


Range = tuple[int, int]


class Rule:
    def __eq__(self, other):
        return isinstance(other, self.__class__)

    def __repr__(self) -> str:
        return f"{self.__class__.__name__}()"

    def __hash__(self):
        return id(self)

    @property
    def __dict__(self):
        return {
            "type": self.__class__.__name__,
        }


@dataclass
class RuleWithValue(Rule):
    value: Any

    def __eq__(self, other):
        return isinstance(other, self.__class__) and self.value == other.value

    def __repr__(self) -> str:
        return f"{self.__class__.__name__}(value={self.value})"

    @property
    def __dict__(self):
        return {
            **super().__dict__,
            "value": self.value,
        }


@dataclass
class RuleWithListOfIntsOrRanges(RuleWithValue):
    value: list[int | Range] = field(
        default_factory=list,
        metadata={"validate": validate_non_empty},
    )

    def __post_init__(self):
        self.value = self.value.copy()


@dataclass
class RuleChar(RuleWithListOfIntsOrRanges):
    def __hash__(self):
        return id(self)


class RuleCharExclude(RuleWithListOfIntsOrRanges):
    def __hash__(self):
        return id(self)


class RuleEnd(Rule):
    def __hash__(self):
        return id(self)


UnresolvedRule = RuleChar | RuleCharExclude | RuleRef | RuleEnd


