    try {
      parseName(src, 0);
    } catch (err) {
      thrown = err;
    }
    expect(thrown).toBeInstanceOf(GrammarParseError);
    expect(String(thrown)).toBe(String(new GrammarParseError(src, 0, PARSE_NAME_ERROR)));
  });
});

