32	  constructor(grammar: string, stackedRules: UnresolvedRule[][][], rootId: number) {
33	    this.grammar = grammar;
34	    const ruleRefs: RuleRef[] = [];
35	    const uniqueRules = new Map<string, UnresolvedRule>();
36	
37	    for (let stackId = 0; stackId < stackedRules.length; stackId++) {
38	      const stack = stackedRules[stackId];
39	      const nodes: RootNode = new Map();
40	      for (let pathId = 0; pathId < stack.length; pathId++) {
41	        const path = stack[pathId];
42	        let node: GraphNode | null = null;
43	        for (let stepId = path.length - 1; stepId >= 0; stepId--) {
44	          const nextNode: GraphNode | null = node;
45	          const rule = stack[pathId][stepId];
46	          uniqueRules.set(getSerializedRuleKey(rule), rule);
47	          if (isRuleRef(rule)) {
48	            ruleRefs.push(rule);
49	          }
50	          // rules coming in may be identical but have different references.
51	          // here, we ensure we always use the same reference for an identical rule.
52	          // this makes future comparisons easier.
53	          const uniqueRule = uniqueRules.get(getSerializedRuleKey(rule));
54	          if (uniqueRule === undefined) {
55	            throw new Error('Could not get unique rule');
56	          }
57	          node = new GraphNode(
58	            uniqueRule,
59	            {
