            [
                RuleCharExclude(value=[ord("x")]),
                RuleEnd(),
            ],
            [
                RuleChar(value=[ord("y")]),
                RuleEnd(),
            ],
            [
                RuleCharExclude(value=[ord("z")]),
                RuleEnd(),
            ],
        ]

    def test_it_builds_rule_stack_for_char_not_with_two_characters_and_a_range():
        result = build_rule_stack(
            [
                ichar_not([ord("x")]),
                ichar_alt(ord("y")),
                ichar_alt(ord("z")),
